@echo off
@setlocal enabledelayedexpansion


for /f "skip=2 tokens=3" %%i in ('reg query "HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\services\MySQL" /v ImagePath') do (
   set temp_str=%%i      
)

rem echo %temp_str%

for /f "tokens=1,2 delims=" %%a in ("%temp_str%") do (
   set MYSQL_STR=%%a\%%b\r
)

@echo MYSQL PATH=%MYSQL_STR%
@echo.

set MYSQL_BIN=%MYSQL_STR%bin\mysql.exe

@echo ******turn off failed login attempts control******
%MYSQL_BIN% -uroot -pvislecaina -e"uninstall plugin connection_control;"
%MYSQL_BIN% -uroot -pvislecaina -e"uninstall plugin connection_control_failed_login_attempts"


@echo done.
pause

